from pathlib import Path
import json
B=Path(__file__).resolve().parents[1]
items=[]
def add(owner,method,path,purpose,fields,guard):
 items.append(dict(id='MS-PROP-%03d'%(len(items)+1),owner=owner,method=method,path=path,purpose=purpose,request_fields=fields.split(),guard=guard,status='PROPOSED_NOT_IMPLEMENTED',canonical_baseline=False))
add('S01','POST','/v1/tenants','Enroll an organization','display_name region_policy_ref initial_owner_subject','platform.tenant.admit with independently approved bootstrap proof')
add('S01','GET','/v1/environments','List current permitted environments','','identity.environment.read')
add('S01','POST','/v1/environments','Create an owned environment','name provider_scope data_policy_ref reason','identity.environment.manage')
for method,path,purpose,fields in [('GET','/v1/connections','List permitted connections',''),('POST','/v1/connections','Enroll a provider/source connection','name provider credential_reference allowed_scopes source_capabilities owner_id reason'),('GET','/v1/connections/{id}','Read connection and verification state',''),('POST','/v1/connections/{id}:verify','Verify actual read-only source access','expected_revision reason'),('POST','/v1/connections/{id}:retire','Stop new collection and retain history','expected_revision reason'),('POST','/v1/connections/{id}/discoveries','Start bounded inventory discovery','expected_revision resource_scopes deadline reason'),('GET','/v1/discoveries/{id}','Read source discovery and matching conflicts','')]:add('S03',method,path,purpose,fields,'connection.read for reads; connection.manage or connection.collect for commands; current scope required')
for method,path,purpose,fields in [('POST','/v1/incidents','Retain an attributable incident','workload_id source_case_id observed_from description evidence_refs reason'),('GET','/v1/incidents/{id}','Read incident and learning links',''),('POST','/v1/learning-records','Record hypotheses actions owners and closure tests','incident_id experiment_id hypotheses action_items evidence_refs expected_revision reason'),('POST','/v1/forecasts','Request an approved advisory forecast','workload_id model_version feature_set_ref feature_set_digest horizon_seconds mode deadline reason'),('GET','/v1/forecasts/{id}','Read forecast lineage uncertainty and evaluation',''),('POST','/v1/model-versions','Retain a model card and immutable version','model_id version artifact_ref digest model_card_ref evaluation_pack_ref reason'),('POST','/v1/model-versions/{id}:review','Independently decide a model version','expected_revision decision evaluation_result_ids reason'),('POST','/v1/model-versions/{id}:promote','Activate only a reviewed passing model version','expected_revision target_mode reason'),('GET','/v1/workloads/{id}/score','Read separately calibrated quantitative results','')]:add('S07',method,path,purpose,fields,'assessment/model/learning capability as appropriate; current source receipts; independent promotion; feature gates apply')
for method,path,purpose,fields in [('POST','/v1/workflows','Retain a bounded workflow definition','workload_id provider_plan_id validation_plan_id recovery_path_id deadline reason'),('GET','/v1/workflows/{id}','Read steps attempts budgets and observed outcomes',''),('POST','/v1/workflows/{id}:cancel','Fence new dispatch and retain in-flight outcomes','expected_revision control_generation reason'),('GET','/v1/provider-plans/{id}','Read immutable translated plan and preconditions',''),('GET','/v1/execution-attempts/{id}','Read attributable provider attempt and uncertainty','')]:add('S11',method,path,purpose,fields,'execution read/manage capability; S10 permits required for effects; cancellation does not erase accepted effects')
add('S12','POST','/v1/recovery-paths','Retain a versioned recovery definition','workload_id scenario failure_domains steps probe_requirements artifact_ref digest reason','recovery.path.manage; actual certification remains separate')
add('S12','GET','/v1/validation-results/{id}','Read independent observed probe outcome','','validation.read plus source disclosure')
for method,path,purpose,fields in [('POST','/v1/billing/accounts','Create a tenant commercial account','customer_id currency billing_contact tax_profile_ref reason'),('GET','/v1/billing/accounts/{id}','Read account and frozen commercial terms',''),('POST','/v1/billing/plan-versions','Draft a versioned commercial plan','plan_id version currency metrics allowances prices effective_from terms_ref reason'),('POST','/v1/billing/plan-versions/{id}:review','Independently approve exact plan version','expected_revision decision reason'),('POST','/v1/billing/subscriptions','Create a governed subscription','account_id approved_plan_version_id starts_at charging_policy_ref reason'),('GET','/v1/billing/subscriptions/{id}','Read subscription and effective periods',''),('POST','/v1/billing/subscriptions/{id}:change','Schedule bounded subscription change','expected_revision approved_plan_version_id effective_at reason'),('POST','/v1/billing/subscriptions/{id}:cancel','Schedule cancellation under the contract','expected_revision effective_at reason'),('POST','/v1/billing/periods/{id}:rate','Rate admitted measured usage once','expected_revision usage_cutoff reason'),('POST','/v1/billing/invoices','Draft an invoice for a frozen period','account_id period_id rated_usage_ids reason'),('POST','/v1/billing/invoices/{id}:post','Post an immutable reviewed invoice','expected_revision reason'),('GET','/v1/billing/invoices/{id}','Read invoice lines taxes and allocations',''),('POST','/v1/billing/payment-attempts','Request collection with stable provider identity','invoice_id amount currency payment_method_ref reason'),('POST','/v1/billing/credits','Record an attributable credit','invoice_id line_allocations amount currency reason evidence_refs'),('POST','/v1/billing/refunds','Request bounded refund against paid allocation','payment_id credit_id amount currency reason'),('POST','/v1/billing/reconciliations','Reconcile source usage invoices and provider settlements','account_id period_id source_cutoff reason'),('POST','/v1/billing/provider-webhooks/{provider}','Admit a signed provider event','provider_event_id signed_payload')]:add('S13',method,path,purpose,fields,'Current tenant finance capability and independent review where required; webhook uses verified provider signature and allowlisted source, never a finance role')
for method,path,purpose,fields in [('GET','/v1/activity','Read scoped recent activity and projection watermark',''),('POST','/v1/notification-routes','Create owner-aware finding delivery policy','workload_scope event_types destination_reference escalation_policy reason'),('POST','/v1/notification-routes/{id}:update','Revise routing without hiding prior deliveries','expected_revision destination_reference escalation_policy reason'),('POST','/v1/evidence/bundles','Request sealed export after source-owner disclosure','source_references purpose classification deadline reason')]:add('S14',method,path,purpose,fields,'audit.read/export or notification.manage with current source and destination policy')
existing={r['endpoint'] for r in json.loads((B/'inventories/API_OWNERSHIP.json').read_text())}
assert all(i['method']+' '+i['path'] not in existing for i in items)
(B/'TARGET_API_ADDITIONS.json').write_text(json.dumps(items,indent=2)+'\n')
text='''# Additional target API capabilities

Version 1.0 | Architecture revision MS 01

The source contains 144 documented operations. The following proposed target additions fill customer-facing gaps for environment/connection enrollment, learning/prediction, workflow status, billing administration and reporting. They are not part of the historical 74 canonical operations and have no implemented-handler claim. Existing operations retain their own wire contracts. These records specify architecture-level fields and guards; milestone implementation publishes closed request/response DTOs and lifecycle constraints before exposing a new route.

All commands use the common idempotency/revision, current identity, scoped disclosure and retained audit rules. Reads paginate bounded collections. Unknown quantities are null rather than invented values. Monetary values use exact decimal strings and explicit currency. Caller fields never select reviewer identity, qualified state, authority tier or verified flags. A webhook signature is checked over its original bounded bytes before normalization.

'''
for service in sorted({i['owner'] for i in items}):
 text+='## '+service+' target additions\n\n'
 for i in items:
  if i['owner']!=service:continue
  text+=f"- **{i['method']} {i['path']}**. {i['purpose']}. "+('Inputs: '+', '.join(i['request_fields'])+'. ' if i['request_fields'] else '')+'Guard: '+i['guard']+'.\n'
 text+='\n'
text+='''## Publication and completion gate

Each addition receives a stable operation ID, closed JSON schemas, error and status contracts, owner tables/migrations, current-authorization checks, idempotency semantics, restrictive sequence/activity alternatives and positive/adverse executed tests. Architecture coverage does not substitute for those implementation deliverables. Provider webhook admission acknowledges retained receipt only; invoice/payment/refund completion remains a separate observed ledger outcome.
'''
(B/'TARGET_API_ADDITIONS.md').write_text(text)
print(len(items),'proposed additions')
